export interface FlagConfig {
  verbose: boolean;
  quiet: boolean;
  outputPath: string | null;
  format: string;
  maxRetries: number;
  timeoutMs: number;
  dryRun: boolean;
  force: boolean;
  logLevel: string;
  configPath: string | null;
  parallelism: number;
  color: boolean;
  strict: boolean;
}

const ALIASES: Record<string, string> = {
  "-v": "--verbose",
  "-q": "--quiet",
  "-f": "--force",
  "-o": "--output",
};

const BOOLEAN_FLAGS: Record<string, keyof FlagConfig> = {
  "--verbose": "verbose",
  "--quiet": "quiet",
  "--dry-run": "dryRun",
  "--force": "force",
  "--strict": "strict",
};

const ENUM_FLAGS: Record<string, { key: keyof FlagConfig; allowed: string[]; label: string }> = {
  "--format": { key: "format", allowed: ["json", "yaml", "text"], label: "format" },
  "--log-level": { key: "logLevel", allowed: ["debug", "info", "warn", "error"], label: "log level" },
};

const INT_FLAGS: Record<string, keyof FlagConfig> = {
  "--retries": "maxRetries",
  "--timeout": "timeoutMs",
  "--parallel": "parallelism",
};

const STRING_FLAGS: Record<string, keyof FlagConfig> = {
  "--output": "outputPath",
  "--config": "configPath",
};

function defaultFlagConfig(): FlagConfig {
  return {
    verbose: false,
    quiet: false,
    outputPath: null,
    format: "text",
    maxRetries: 3,
    timeoutMs: 30000,
    dryRun: false,
    force: false,
    logLevel: "info",
    configPath: null,
    parallelism: 1,
    color: true,
    strict: false,
  };
}

type MutableConfig = Record<keyof FlagConfig, unknown>;

export function parseFlags(argv: string[]): FlagConfig {
  const config = defaultFlagConfig() as unknown as MutableConfig;

  let i = 0;
  while (i < argv.length) {
    const arg = ALIASES[argv[i]!] ?? argv[i]!;

    if (arg === "--no-color") {
      config.color = false;
      i += 1;
      continue;
    }

    const boolKey = BOOLEAN_FLAGS[arg];
    if (boolKey !== undefined) {
      config[boolKey] = true;
      i += 1;
      continue;
    }

    const stringKey = STRING_FLAGS[arg];
    if (stringKey !== undefined) {
      config[stringKey] = requireStringValue(argv, i + 1, arg);
      i += 2;
      continue;
    }

    const enumSpec = ENUM_FLAGS[arg];
    if (enumSpec !== undefined) {
      config[enumSpec.key] = requireEnumValue(argv, i + 1, enumSpec.allowed, enumSpec.label);
      i += 2;
      continue;
    }

    const intKey = INT_FLAGS[arg];
    if (intKey !== undefined) {
      config[intKey] = requireIntValue(argv, i + 1, arg);
      i += 2;
      continue;
    }

    throw new Error(`unknown flag: ${arg}`);
  }

  return config as unknown as FlagConfig;
}

function requireStringValue(argv: string[], index: number, flag: string): string {
  const value = argv[index];
  if (value === undefined) throw new Error(`${flag} requires a path`);
  return value;
}

function requireEnumValue(argv: string[], index: number, allowed: string[], label: string): string {
  const value = argv[index];
  if (value === undefined || !allowed.includes(value)) throw new Error(`unsupported ${label}: ${String(value)}`);
  return value;
}

function requireIntValue(argv: string[], index: number, flag: string): number {
  const value = Number(argv[index]);
  if (!Number.isInteger(value)) throw new Error(`${flag} must be an integer`);
  return value;
}

export interface FlagConfig {
  verbose: boolean;
  quiet: boolean;
  outputPath: string | null;
  format: string;
  maxRetries: number;
  timeoutMs: number;
  dryRun: boolean;
  force: boolean;
  logLevel: string;
  configPath: string | null;
  parallelism: number;
  color: boolean;
  strict: boolean;
}

const ALIASES: Record<string, string> = {
  "-v": "--verbose",
  "-q": "--quiet",
  "-f": "--force",
  "-o": "--output",
};

function normalizeFlag(arg: string): string {
  return ALIASES[arg] ?? arg;
}

function defaultFlagConfig(): FlagConfig {
  return {
    verbose: false,
    quiet: false,
    outputPath: null,
    format: "text",
    maxRetries: 3,
    timeoutMs: 30000,
    dryRun: false,
    force: false,
    logLevel: "info",
    configPath: null,
    parallelism: 1,
    color: true,
    strict: false,
  };
}

export function parseFlags(argv: string[]): FlagConfig {
  const config = defaultFlagConfig();

  for (let i = 0; i < argv.length; i++) {
    const arg = normalizeFlag(argv[i]!);

    if (arg === "--verbose") {
      setVerbose(config);
    } else if (arg === "--quiet") {
      setQuiet(config);
    } else if (arg === "--dry-run") {
      setDryRun(config);
    } else if (arg === "--force") {
      setForce(config);
    } else if (arg === "--no-color") {
      disableColor(config);
    } else if (arg === "--strict") {
      setStrict(config);
    } else if (arg === "--output") {
      const value = argv[++i];
      if (value === undefined) {
        throw new Error("--output requires a path");
      }
      config.outputPath = value;
    } else if (arg === "--config") {
      const value = argv[++i];
      if (value === undefined) {
        throw new Error("--config requires a path");
      }
      config.configPath = value;
    } else if (arg === "--format") {
      const value = argv[++i];
      if (value === undefined || !["json", "yaml", "text"].includes(value)) {
        throw new Error(`unsupported format: ${String(value)}`);
      }
      config.format = value;
    } else if (arg === "--log-level") {
      const value = argv[++i];
      if (value === undefined || !["debug", "info", "warn", "error"].includes(value)) {
        throw new Error(`unsupported log level: ${String(value)}`);
      }
      config.logLevel = value;
    } else if (arg === "--retries") {
      const value = Number(argv[++i]);
      if (!Number.isInteger(value)) {
        throw new Error("--retries must be an integer");
      }
      config.maxRetries = value;
    } else if (arg === "--timeout") {
      const value = Number(argv[++i]);
      if (!Number.isInteger(value)) {
        throw new Error("--timeout must be an integer");
      }
      config.timeoutMs = value;
    } else if (arg === "--parallel") {
      const value = Number(argv[++i]);
      if (!Number.isInteger(value)) {
        throw new Error("--parallel must be an integer");
      }
      config.parallelism = value;
    } else {
      throw new Error(`unknown flag: ${arg}`);
    }
  }

  return config;
}

function setVerbose(config: FlagConfig): void { config.verbose = true; }
function setQuiet(config: FlagConfig): void { config.quiet = true; }
function setDryRun(config: FlagConfig): void { config.dryRun = true; }
function setForce(config: FlagConfig): void { config.force = true; }
function disableColor(config: FlagConfig): void { config.color = false; }
function setStrict(config: FlagConfig): void { config.strict = true; }

